function money(n){return isFinite(n)?n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}):'-';}
// EMI = P r (1+r)^n / ((1+r)^n - 1); 0% interest gives P / n
function emi(){var box=h('div',{class:'panel'}),res=h('div',{class:'panel'}),f=[field('Loan amount','a',{type:'number',value:'1000000',min:'0'}),field('Yearly interest rate (%)','r',{type:'number',value:'8.5',min:'0',step:'0.01'}),field('Years','y',{type:'number',value:'20',min:'1',step:'1'})];
f.forEach(function(p){p.forEach(function(x){box.appendChild(x);});});
function calc(){var P=+f[0][1].value,r=+f[1][1].value/1200,n=Math.round(+f[2][1].value*12),m;
if(!(P>0)||!(n>0)||r<0){res.replaceChildren(h('p',{text:'Enter a loan amount, a rate and the years.'}));return;}
m=r===0?P/n:P*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1);
res.replaceChildren(h('div',{text:'Monthly EMI'}),h('div',{class:'big',text:money(m)}),h('p',{text:'Total interest: '+money(m*n-P)}),h('p',{text:'Total payment: '+money(m*n)}),h('p',{class:'sub',text:'Estimates only. Real loans may have fees. Not financial advice.'}));}
box.addEventListener('input',calc);calc();
shell('EMI Calculator','See your monthly loan payment as you type.',h('div',{},box,res));}
function utc(s){var p=s.split('-');return Date.UTC(+p[0],+p[1]-1,+p[2]);}
function dim(y,m){return new Date(Date.UTC(y,m+1,0)).getUTCDate();}
function age(){var box=h('div',{class:'panel'}),res=h('div',{class:'panel'}),t=new Date(),iso=t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');
var a=field('Date of birth','b',{type:'date'}),b=field('Age as of','o',{type:'date',value:iso});[a,b].forEach(function(p){p.forEach(function(x){box.appendChild(x);});});
function calc(){var bs=a[1].value,os=b[1].value;if(!bs||!os){res.replaceChildren(h('p',{text:'Choose a date of birth.'}));return;}
var B=new Date(utc(bs)),O=new Date(utc(os));if(B>O){res.replaceChildren(h('p',{text:'That date is in the future. Please check it.'}));return;}
var tm=(O.getUTCFullYear()-B.getUTCFullYear())*12+(O.getUTCMonth()-B.getUTCMonth());if(O.getUTCDate()<B.getUTCDate())tm--;
var ay=B.getUTCFullYear()+Math.floor((B.getUTCMonth()+tm)/12),am=(B.getUTCMonth()+tm)%12,anc=Date.UTC(ay,am,Math.min(B.getUTCDate(),dim(ay,am)));
var y=Math.floor(tm/12),m=tm%12,d=Math.round((O-anc)/864e5);function pl(n,w){return n+' '+w+(n===1?'':'s');}
var days=Math.round((O-B)/864e5),Y=O.getUTCFullYear(),bm=B.getUTCMonth(),bd=B.getUTCDate(),nb;
function bday(yr){var dd=(bm===1&&bd===29&&dim(yr,1)===28)?28:bd;return Date.UTC(yr,bm,dd);}
nb=bday(Y);if(nb<O)nb=bday(Y+1);
var wd=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][B.getUTCDay()];
res.replaceChildren(h('div',{class:'big',text:pl(y,'year')+', '+pl(m,'month')+', '+pl(d,'day')}),h('p',{text:'Total days lived: '+days.toLocaleString()}),h('p',{text:'Total weeks: '+Math.floor(days/7).toLocaleString()}),h('p',{text:'Born on a '+wd}),h('p',{text:'Next birthday in '+Math.round((nb-O)/864e5)+' days'}),
(bm===1&&bd===29)?h('p',{class:'sub',text:'In non-leap years a 29 February birthday is counted as 28 February.'}):null);}
box.addEventListener('input',calc);calc();
shell('Age Calculator','Your exact age in years, months and days.',h('div',{},box,res));}
// Passwords use crypto.getRandomValues with rejection sampling, so there is no bias. Nothing is stored.
function rnd(n){var lim=Math.floor(4294967296/n)*n,a=new Uint32Array(1);do{crypto.getRandomValues(a);}while(a[0]>=lim);return a[0]%n;}
function pw(){var box=h('div',{class:'panel'}),res=h('div',{class:'panel'}),L=field('Length (8 to 128)','l',{type:'number',value:'16',min:'8',max:'128'});L.forEach(function(x){box.appendChild(x);});
var sets=[['Uppercase','ABCDEFGHIJKLMNOPQRSTUVWXYZ'],['Lowercase','abcdefghijklmnopqrstuvwxyz'],['Digits','0123456789'],['Symbols','!@#$%^&*()-_=+[]{};:,.?']],cb=[];
sets.forEach(function(s,i){var c=h('input',{type:'checkbox',id:'c'+i,checked:'checked'});cb.push(c);box.appendChild(h('div',{class:'row'},c,h('label',{for:'c'+i,text:s[0],class:'tight'})));});
var ex=h('input',{type:'checkbox',id:'ex'});box.appendChild(h('div',{class:'row'},ex,h('label',{for:'ex',text:'Skip look-alikes (O 0 l 1 I)',class:'tight'})));
var out=h('div',{class:'out',text:'-'}),info=h('p',{class:'sub'});
function gen(){var n=Math.min(128,Math.max(8,+L[1].value||16)),pools=[];
sets.forEach(function(s,i){if(cb[i].checked){var p=s[1];if(ex.checked)p=p.replace(/[O0l1I]/g,'');pools.push(p);}});
if(!pools.length){out.textContent='Choose at least one type.';info.textContent='';return;}
var all=pools.join(''),r=[];pools.forEach(function(p){r.push(p[rnd(p.length)]);});while(r.length<n)r.push(all[rnd(all.length)]);
for(var i=r.length-1;i>0;i--){var j=rnd(i+1),t=r[i];r[i]=r[j];r[j]=t;}
var bits=Math.round(n*Math.log2(all.length));out.textContent=r.join('');
info.textContent='Strength: '+(bits<50?'weak':bits<70?'fair':bits<100?'strong':'very strong')+' ('+bits+' bits of entropy)';}
var msg=h('span',{class:'sub'});
box.appendChild(h('button',{type:'button',text:'Generate',on:{click:gen}}));
box.appendChild(h('button',{type:'button',text:'Copy',on:{click:function(){cp(out.textContent,msg);}}}));box.appendChild(msg);
res.appendChild(out);res.appendChild(info);gen();
shell('Password Generator','Strong random passwords. Never stored, never sent.',h('div',{},box,res));}

